/**
 * Langfuse/OpenTelemetry wiring for Browser Agent SDK runs.
 *
 * The SDK already emits AI SDK spans (system prompt, tool definitions, messages,
 * tool args/results, usage, latency) and its own run/browser-command spans
 * through the host's global tracer provider (`src/lib/telemetry/otel.ts`). Two
 * things are the host's call and live here:
 *
 * - Content recording. Off unless `BROWSER_AGENT_TRACE_CONTENT=true`, because a
 *   recorded prompt carries the application URL and login credentials verbatim
 *   — enable it only where the trace backend may hold them (local, QA).
 * - A root span per run carrying Langfuse trace attributes, so every model call,
 *   tool call and browser command of one run lands in one named, filterable trace.
 */

import { SpanStatusCode, trace, type Attributes } from '@opentelemetry/api'
import type { AgentConfig } from '@acme/browser-agent/api'
import { flushTelemetry } from '@/lib/telemetry/otel'
import type { BrowserAgentSdkOutcome, RunBrowserAgentSdkInput } from './types'

export const TRACE_CONTENT_ENV = 'BROWSER_AGENT_TRACE_CONTENT'

type TelemetrySettings = NonNullable<AgentConfig['telemetry']>

export function browserAgentTelemetrySettings(
  env: Readonly<Record<string, string | undefined>> = process.env,
): TelemetrySettings {
  const recordContent = env[TRACE_CONTENT_ENV] === 'true'
  return { enabled: true, recordInputs: recordContent, recordOutputs: recordContent }
}

function traceAttributes(
  input: RunBrowserAgentSdkInput,
  recordContent: boolean,
): Attributes {
  const preset = input.preset ?? 'generation'
  return {
    'langfuse.trace.name': `browser-agent.${preset}.${input.subject.type}`,
    'langfuse.session.id': input.correlationId,
    'langfuse.trace.tags': [preset, input.subject.type, input.modelId],
    'langfuse.trace.metadata.tenantId': input.tenantId,
    'langfuse.trace.metadata.subjectType': input.subject.type,
    'langfuse.trace.metadata.subjectId': input.subject.id,
    'langfuse.trace.metadata.modelId': input.modelId,
    'langfuse.trace.metadata.requiresLogin': input.requiresLogin,
    'langfuse.trace.metadata.preLogin': Boolean(input.login),
    ...(recordContent ? { 'langfuse.trace.input': JSON.stringify(input.task) } : {}),
  }
}

function outcomeSummary(outcome: BrowserAgentSdkOutcome): string {
  switch (outcome.status) {
    case 'success':
      return JSON.stringify({ status: outcome.status, summary: outcome.summary })
    case 'agent-failure':
      return JSON.stringify({ status: outcome.status, reason: outcome.reason })
    case 'operational-failure':
      return JSON.stringify({ status: outcome.status, failure: outcome.failure })
  }
}

/**
 * Run `operation` inside a root span for one Browser Agent SDK run, then flush
 * so the trace is visible immediately — and survives a worker that exits right
 * after a failing run. No-op cost when no tracer provider is registered.
 */
export async function withBrowserAgentTrace(
  input: RunBrowserAgentSdkInput,
  operation: () => Promise<BrowserAgentSdkOutcome>,
): Promise<BrowserAgentSdkOutcome> {
  const recordContent = browserAgentTelemetrySettings().recordOutputs === true
  const tracer = trace.getTracer('aionq-browser-agent-sdk')
  try {
    return await tracer.startActiveSpan(
      'aionq.browser_agent.run',
      { attributes: traceAttributes(input, recordContent) },
      async (span) => {
        try {
          const outcome = await operation()
          span.setAttribute('aionq.browser_agent.outcome', outcome.status)
          span.setAttribute('aionq.browser_agent.sdk_run_id', outcome.sdkRunId)
          if (recordContent) span.setAttribute('langfuse.trace.output', outcomeSummary(outcome))
          if (outcome.status !== 'success') span.setStatus({ code: SpanStatusCode.ERROR })
          return outcome
        } catch (error: unknown) {
          span.setStatus({ code: SpanStatusCode.ERROR })
          throw error
        } finally {
          span.end()
        }
      },
    )
  } finally {
    await flushTelemetry()
  }
}

