import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from 'vitest'
import { trace } from '@opentelemetry/api'
import {
  BasicTracerProvider,
  InMemorySpanExporter,
  SimpleSpanProcessor,
} from '@opentelemetry/sdk-trace-base'
import { REPLAY_CONTRACT_VERSION } from '@acme/browser-agent/api'

const flushTelemetry = vi.fn(async () => undefined)
vi.mock('@/lib/telemetry/otel', () => ({ flushTelemetry }))

const { browserAgentTelemetrySettings, withBrowserAgentTrace, TRACE_CONTENT_ENV } =
  await import('../telemetry')
import type { BrowserAgentSdkOutcome, RunBrowserAgentSdkInput } from '../types'

const exporter = new InMemorySpanExporter()

const input = {
  modelId: 'test-model',
  url: 'https://example.test',
  subject: { type: 'test-case', id: 'case-1' },
  task: { title: 'Example', steps: '1. Open the form' },
  tenantId: 'tenant-1',
  correlationId: 'corr-1',
  requiresLogin: false,
} as unknown as RunBrowserAgentSdkInput

const base = {
  sdkRunId: 'sdk-run',
  plan: { contractVersion: REPLAY_CONTRACT_VERSION, steps: [] },
  expectationCoverage: [],
  recorderSteps: [],
  usage: { promptTokens: 0, completionTokens: 0, totalTokens: 0 },
  versions: {
    packageVersion: 'x',
    eventSchemaVersion: 'x',
    replayContractVersion: REPLAY_CONTRACT_VERSION,
    agentPromptVersion: 'x',
  },
}

const failure = {
  ...base,
  status: 'agent-failure',
  reason: 'could not find the form',
} as unknown as BrowserAgentSdkOutcome

beforeAll(() => {
  trace.setGlobalTracerProvider(
    new BasicTracerProvider({ spanProcessors: [new SimpleSpanProcessor(exporter)] }),
  )
})

afterEach(() => {
  exporter.reset()
  vi.unstubAllEnvs()
  flushTelemetry.mockClear()
})

afterAll(() => {
  trace.disable()
})

describe('browserAgentTelemetrySettings', () => {
  it('enables spans but not content by default', () => {
    expect(browserAgentTelemetrySettings({})).toEqual({
      enabled: true,
      recordInputs: false,
      recordOutputs: false,
    })
  })

  it('records content only when the flag is exactly "true"', () => {
    expect(browserAgentTelemetrySettings({ [TRACE_CONTENT_ENV]: 'true' })).toMatchObject({
      recordInputs: true,
      recordOutputs: true,
    })
    expect(browserAgentTelemetrySettings({ [TRACE_CONTENT_ENV]: '1' })).toMatchObject({
      recordInputs: false,
    })
  })
})

describe('withBrowserAgentTrace', () => {
  it('wraps the run in one Langfuse-attributed root span and flushes', async () => {
    const outcome = await withBrowserAgentTrace(input, async () => failure)

    expect(outcome).toBe(failure)
    const [span] = exporter.getFinishedSpans()
    expect(span?.name).toBe('aionq.browser_agent.run')
    expect(span?.attributes).toMatchObject({
      'langfuse.trace.name': 'browser-agent.generation.test-case',
      'langfuse.session.id': 'corr-1',
      'langfuse.trace.metadata.tenantId': 'tenant-1',
      'langfuse.trace.metadata.subjectId': 'case-1',
      'aionq.browser_agent.outcome': 'agent-failure',
    })
    expect(span?.attributes['langfuse.trace.input']).toBeUndefined()
    expect(span?.status.code).toBe(2)
    expect(flushTelemetry).toHaveBeenCalledOnce()
  })

  it('records trace input/output when content recording is on', async () => {
    vi.stubEnv(TRACE_CONTENT_ENV, 'true')

    await withBrowserAgentTrace(input, async () => failure)

    const [span] = exporter.getFinishedSpans()
    expect(span?.attributes['langfuse.trace.input']).toBe(JSON.stringify(input.task))
    expect(span?.attributes['langfuse.trace.output']).toContain('could not find the form')
  })

  it('still ends the span and flushes when the run throws', async () => {
    await expect(
      withBrowserAgentTrace(input, async () => {
        throw new Error('boom')
      }),
    ).rejects.toThrow('boom')

    expect(exporter.getFinishedSpans()).toHaveLength(1)
    expect(flushTelemetry).toHaveBeenCalledOnce()
  })
})
